     1	import { supabase } from '@/lib/supabase';
     2	import { toReadableError } from '@/services/function-errors';
     3	
     4	/**
     5	 * Gets a temporary (30-second) Deepgram token from the `deepgram-token` Edge Function.
     6	 * The permanent Deepgram key never leaves the server.
     7	 */
     8	export async function fetchDeepgramToken(): Promise<string> {
     9	  const { data, error } = await supabase.functions.invoke<{ access_token: string }>(
    10	    'deepgram-token',
    11	    { method: 'POST' }
    12	  );
    13	
    14	  if (error) {
    15	    throw await toReadableError(error, 'Couldn’t connect to your dream companion.');
    16	  }
    17	  if (typeof data?.access_token !== 'string' || data.access_token === '') {
    18	    throw new Error('Couldn’t connect to your dream companion.');
    19	  }
    20	  return data.access_token;
    21	}

########## hooks/use-voice-agent.ts ##########
     1	import { useCallback, useEffect, useReducer, useRef } from 'react';
     2	import { AppState } from 'react-native';
     3	import { useSharedValue } from 'react-native-reanimated';
     4	
     5	import { VoiceAgentClient } from '@/lib/deepgram/client';
     6	import { buildSettings, OUTPUT_SAMPLE_RATE } from '@/lib/deepgram/messages';
     7	import { loadNativeAudio, type NativeAudio } from '@/lib/deepgram/native-audio';
     8	import { PlaybackQueue } from '@/lib/deepgram/playback-queue';
     9	import type { DreamContext, ServerMessage, TranscriptEntry } from '@/lib/deepgram/types';
    10	import { initialVoiceState, voiceReducer } from '@/lib/deepgram/voice-state';
    11	import { fetchDeepgramToken } from '@/services/voice-agent';
    12	import { getErrorMessage } from '@/utils/errors';
    13	
    14	const UNSUPPORTED_MESSAGE =
    15	  'The voice companion needs the app’s development build. It doesn’t run in Expo Go.';
    16	const PERMISSION_MESSAGE = 'Microphone access is off, so your dream companion can’t hear you.';
    17	const AUDIO_START_MESSAGE = 'Couldn’t start the microphone or speaker. Please try again.';
    18	const AGENT_ERROR_MESSAGE = 'Your dream companion ran into a problem. Please try again.';
    19	
    20	type Subscription = { remove: () => void };
    21	
    22	/** Everything that belongs to one connection, so it can all be cleaned up together. */
    23	type Session = {
    24	  audio: NativeAudio;
    25	  client: VoiceAgentClient | null;
    26	  queue: PlaybackQueue | null;
    27	  subscriptions: Subscription[];
    28	  cancelled: boolean;
    29	};
    30	
    31	/**
    32	 * Runs a real-time voice conversation with the Deepgram Voice Agent.
    33	 *
    34	 * Microphone (16 kHz PCM, echo-cancelled) → WebSocket → Deepgram (speech-to-text + LLM + voice)
    35	 * → agent audio → paced playback queue → speaker.
    36	 *
    37	 * `dream` (optional) is the selected dream's context for the companion.
    38	 */
    39	export function useVoiceAgent(dream: DreamContext | null) {
    40	  const [state, dispatch] = useReducer(voiceReducer, initialVoiceState);
    41	  // Live audio levels (0–1) for the orb animation; updated without re-rendering.
    42	  const inputLevel = useSharedValue(0);
    43	  const outputLevel = useSharedValue(0);
    44	
    45	  const sessionRef = useRef<Session | null>(null);
    46	  const mutedRef = useRef(false);
    47	  const audioReadyRef = useRef(false);
    48	  // Latest transcript, read when reconnecting so the conversation can continue.
    49	  const transcriptRef = useRef<TranscriptEntry[]>([]);
    50	  useEffect(() => {
    51	    transcriptRef.current = state.transcript;
    52	  }, [state.transcript]);
    53	
    54	  /** Closes the socket, stops the mic, drops queued audio and removes every listener. */
    55	  const stopSession = useCallback(() => {
    56	    const session = sessionRef.current;
    57	    sessionRef.current = null;
    58	    if (!session) return;
    59	    session.cancelled = true;
    60	    session.subscriptions.forEach((subscription) => subscription.remove());
    61	    session.queue?.dispose();
    62	    session.client?.close();
    63	    try {
    64	      session.audio.toggleRecording(false);
    65	    } catch {
    66	      // Audio engine already torn down.
    67	    }
    68	    inputLevel.set(0);
    69	    outputLevel.set(0);
    70	  }, [inputLevel, outputLevel]);
    71	
    72	  const start = useCallback(async () => {
    73	    stopSession();
    74	    dispatch({ type: 'connect' });
    75	
    76	    const audio = loadNativeAudio();
    77	    if (!audio) {
    78	      dispatch({ type: 'error', kind: 'unsupported', message: UNSUPPORTED_MESSAGE });
    79	      return;
    80	    }
    81	
    82	    const session: Session = { audio, client: null, queue: null, subscriptions: [], cancelled: false };
    83	    sessionRef.current = session;
    84	    // Ignore callbacks from a session the user has already ended or replaced.
    85	    const isCurrent = () => sessionRef.current === session && !session.cancelled;
    86	    const fail = (kind: 'permission' | 'connection' | 'agent', message: string) => {
    87	      if (!isCurrent()) return;
    88	      stopSession();
    89	      dispatch({ type: 'error', kind, message });
    90	    };
    91	
    92	    // 1. Microphone permission and the native audio engine (echo cancellation on).
    93	    try {
    94	      const permission = await audio.requestMicrophonePermissionsAsync();
    95	      if (!isCurrent()) return;
    96	      if (!permission.granted) {
    97	        fail('permission', PERMISSION_MESSAGE);
    98	        return;
    99	      }
   100	      if (!audioReadyRef.current) {
   101	        await audio.initialize();
   102	        audioReadyRef.current = true;
   103	      }
   104	    } catch (error) {
   105	      console.warn('Voice audio setup failed:', error);
   106	      fail('agent', AUDIO_START_MESSAGE);
   107	      return;
   108	    }
   109	    if (!isCurrent()) return;
   110	
   111	    // 2. A temporary Deepgram token from our Edge Function.
   112	    let token: string;
   113	    try {
   114	      token = await fetchDeepgramToken();
   115	    } catch (error) {
   116	      fail('connection', getErrorMessage(error));
   117	      return;
   118	    }
   119	    if (!isCurrent()) return;
   120	
   121	    // 3. Playback of the agent's voice, clearable when the user interrupts.
   122	    const queue = new PlaybackQueue({
   123	      sampleRate: OUTPUT_SAMPLE_RATE,
   124	      play: (chunk) => audio.playPCMData(chunk),
   125	      onDrained: () => {
   126	        if (isCurrent()) dispatch({ type: 'playbackDrained' });
   127	      },
   128	    });
   129	    session.queue = queue;
   130	
   131	    const handleMessage = (message: ServerMessage) => {
   132	      switch (message.type) {
   133	        case 'SettingsApplied':
   134	          // Deepgram is ready: start streaming the microphone.
   135	          audio.toggleRecording(!mutedRef.current);
   136	          dispatch({ type: 'ready' });
   137	          break;
   138	        case 'UserStartedSpeaking':
   139	          // Barge-in: stop the agent's voice right away.
   140	          queue.clear();
   141	          dispatch({ type: 'userStartedSpeaking' });
   142	          break;
   143	        case 'AgentThinking':
   144	          dispatch({ type: 'agentThinking' });
   145	          break;
   146	        case 'AgentStartedSpeaking':
   147	          dispatch({ type: 'agentStartedSpeaking' });
   148	          break;
   149	        case 'AgentAudioDone':
   150	          dispatch({ type: 'agentAudioDone' });
   151	          if (queue.isIdle) dispatch({ type: 'playbackDrained' });
   152	          break;
   153	        case 'ConversationText':
   154	          dispatch({ type: 'transcript', role: message.role, text: message.content });
   155	          break;
   156	        case 'Error':
   157	          console.warn('Deepgram Voice Agent error:', message.code, message.description);
   158	          fail('agent', AGENT_ERROR_MESSAGE);
   159	          break;
   160	        case 'Warning':
   161	          console.warn('Deepgram Voice Agent warning:', message.code, message.description);
   162	          break;
   163	      }
   164	    };
   165	
   166	    // 4. The WebSocket to Deepgram.
   167	    const client = new VoiceAgentClient({
   168	      token,
   169	      settings: buildSettings({ dream, history: transcriptRef.current }),
   170	      handlers: {
   171	        onMessage: (message) => {
   172	          if (isCurrent()) handleMessage(message);
   173	        },
   174	        onAudio: (chunk) => {
   175	          if (isCurrent()) queue.enqueue(chunk);
   176	        },
   177	        onClose: ({ closedByApp, code, reason }) => {
   178	          if (closedByApp || !isCurrent()) return;
   179	          console.warn('Voice Agent connection closed:', code, reason);
   180	          stopSession();
   181	          dispatch({ type: 'disconnected' });
   182	        },
   183	      },
   184	    });
   185	    session.client = client;
   186	
   187	    // 5. Microphone → Deepgram, and audio levels → orb.
   188	    session.subscriptions.push(
   189	      audio.addExpoTwoWayAudioEventListener('onMicrophoneData', (event) => {
   190	        if (isCurrent() && !mutedRef.current) client.sendAudio(event.data);
   191	      }),
   192	      audio.addExpoTwoWayAudioEventListener('onInputVolumeLevelData', (event) => {
   193	        inputLevel.set(event.data);
   194	      }),
   195	      audio.addExpoTwoWayAudioEventListener('onOutputVolumeLevelData', (event) => {
   196	        outputLevel.set(event.data);
   197	      }),
   198	      // A phone call or Siri takes over the audio: end the conversation cleanly.
   199	      audio.addExpoTwoWayAudioEventListener('onAudioInterruption', (event) => {
   200	        // iOS sends 'began', Android sends 'blocked'.
   201	        if (isCurrent() && (event.data === 'began' || event.data === 'blocked')) {
   202	          stopSession();
   203	          dispatch({ type: 'ended' });
   204	        }
   205	      })
   206	    );
   207	
   208	    client.connect();
   209	  }, [dream, stopSession, inputLevel, outputLevel]);
   210	
   211	  const end = useCallback(() => {
   212	    stopSession();
   213	    dispatch({ type: 'ended' });
   214	  }, [stopSession]);
   215	
   216	  const toggleMute = useCallback(() => {
   217	    mutedRef.current = !mutedRef.current;
   218	    const session = sessionRef.current;
   219	    if (session?.client?.isOpen) {
   220	      // Actually switch the microphone off while muted (the KeepAlive keeps the call open).
   221	      session.audio.toggleRecording(!mutedRef.current);
   222	    }
   223	    if (mutedRef.current) inputLevel.set(0);
   224	    dispatch({ type: 'toggleMute' });
   225	  }, [inputLevel]);
   226	
   227	  // Leaving the app: end the conversation so the microphone never runs in the background.
   228	  useEffect(() => {
   229	    const subscription = AppState.addEventListener('change', (appState) => {
   230	      if (appState === 'background' && sessionRef.current) {
   231	        stopSession();
   232	        dispatch({ type: 'ended' });
   233	      }
   234	    });
   235	    return () => subscription.remove();
   236	  }, [stopSession]);
   237	
   238	  // Leaving the screen: clean up everything, including the native audio engine.
   239	  useEffect(() => {
   240	    return () => {
   241	      stopSession();
   242	      if (audioReadyRef.current) {
   243	        try {
   244	          loadNativeAudio()?.tearDown();
   245	        } catch {
   246	          // Already torn down.
   247	        }
   248	        audioReadyRef.current = false;
   249	      }
   250	    };
   251	  }, [stopSession]);
   252	
   253	  return { state, inputLevel, outputLevel, start, end, toggleMute };
   254	}

