########## app/voice.tsx ##########
     1	import { router, useLocalSearchParams } from 'expo-router';
     2	import { StatusBar } from 'expo-status-bar';
     3	import { useEffect, useState } from 'react';
     4	import { ActivityIndicator, Linking, Pressable, StyleSheet, Text, View } from 'react-native';
     5	import { SafeAreaView } from 'react-native-safe-area-context';
     6	
     7	import { VoiceOrb } from '@/components/voice-orb';
     8	import { VoiceTranscript } from '@/components/voice-transcript';
     9	import { Radius, Spacing, VoiceColors } from '@/constants/theme';
    10	import { useVoiceAgent } from '@/hooks/use-voice-agent';
    11	import type { DreamContext } from '@/lib/deepgram/types';
    12	import { isLiveStatus, statusLabel } from '@/lib/deepgram/voice-state';
    13	import { fetchDreamById } from '@/services/dreams';
    14	
    15	/**
    16	 * Voice companion screen ("/voice", or "/voice?dreamId=<id>" to talk about a saved dream).
    17	 * Real-time conversation with the Deepgram Voice Agent. Needs the native development build.
    18	 */
    19	export default function VoiceScreen() {
    20	  const { dreamId } = useLocalSearchParams<{ dreamId?: string }>();
    21	  const { dream, loadingDream } = useDreamContext(dreamId);
    22	  const { state, inputLevel, outputLevel, start, end, toggleMute } = useVoiceAgent(dream);
    23	
    24	  const live = isLiveStatus(state.status);
    25	  const busy = live || state.status === 'connecting';
    26	  const canStart = !busy && !loadingDream && state.error?.kind !== 'unsupported';
    27	
    28	  function handleClose() {
    29	    end();
    30	    router.back();
    31	  }
    32	
    33	  return (
    34	    <SafeAreaView style={styles.screen} edges={['top', 'bottom', 'left', 'right']}>
    35	      <StatusBar style="light" />
    36	
    37	      <View style={styles.header}>
    38	        <Pressable onPress={handleClose} hitSlop={12} accessibilityRole="button" accessibilityLabel="Close">
    39	          <Text style={styles.close}>✕</Text>
    40	        </Pressable>
    41	        <View style={styles.headerText}>
    42	          <Text style={styles.title}>Dream Companion</Text>
    43	          {!!dream?.title && (
    44	            <Text style={styles.subtitle} numberOfLines={1}>
    45	              {dream.title}
    46	            </Text>
    47	          )}
    48	        </View>
    49	        <View style={styles.headerSpacer} />
    50	      </View>
    51	
    52	      <Pressable
    53	        style={styles.orbArea}
    54	        onPress={canStart ? start : undefined}
    55	        accessibilityRole="button"
    56	        accessibilityLabel={canStart ? 'Start conversation' : statusLabel(state)}>
    57	        <VoiceOrb
    58	          status={state.status}
    59	          muted={state.muted}
    60	          inputLevel={inputLevel}
    61	          outputLevel={outputLevel}
    62	        />
    63	        <View style={styles.statusRow}>
    64	          {state.status === 'connecting' && <ActivityIndicator color={VoiceColors.textSecondary} />}
    65	          <Text
    66	            style={[styles.status, state.status === 'error' && styles.statusError]}
    67	            accessibilityLiveRegion="polite">
    68	            {loadingDream ? 'Getting your dream…' : statusLabel(state)}
    69	          </Text>
    70	        </View>
    71	        {state.status === 'idle' && !loadingDream && (
    72	          <Text style={styles.hint}>
    73	            {dream ? 'Talk it through out loud. You can interrupt anytime.' : 'Tell your companion about a dream, out loud.'}
    74	          </Text>
    75	        )}
    76	      </Pressable>
    77	
    78	      <View style={styles.transcript}>
    79	        <VoiceTranscript entries={state.transcript} />
    80	      </View>
    81	
    82	      <View style={styles.controls}>
    83	        {busy ? (
    84	          <>
    85	            <ControlButton
    86	              label={state.muted ? 'Unmute' : 'Mute'}
    87	              onPress={toggleMute}
    88	              disabled={!live}
    89	              variant={state.muted ? 'active' : 'plain'}
    90	            />
    91	            <ControlButton label="End conversation" onPress={end} variant="danger" wide />
    92	          </>
    93	        ) : state.status === 'error' && state.error?.kind === 'unsupported' ? (
    94	          <ControlButton label="Back" onPress={handleClose} wide />
    95	        ) : state.status === 'error' && state.error?.kind === 'permission' ? (
    96	          <>
    97	            <ControlButton label="Open Settings" onPress={() => Linking.openSettings()} />
    98	            <ControlButton label="Try again" onPress={start} variant="primary" wide />
    99	          </>
   100	        ) : (
   101	          <ControlButton
   102	            label={
   103	              state.status === 'error'
   104	                ? state.transcript.length > 0
   105	                  ? 'Reconnect'
   106	                  : 'Try again'
   107	                : state.status === 'ended'
   108	                  ? 'Start a new conversation'
   109	                  : 'Start conversation'
   110	            }
   111	            onPress={start}
   112	            disabled={!canStart}
   113	            variant="primary"
   114	            wide
   115	          />
   116	        )}
   117	      </View>
   118	    </SafeAreaView>
   119	  );
   120	}
   121	
   122	/** Loads the selected dream (only the fields the companion needs), if one was passed. */
   123	function useDreamContext(dreamId: string | undefined) {
   124	  const [dream, setDream] = useState<DreamContext | null>(null);
   125	  const [loadingDream, setLoadingDream] = useState(!!dreamId);
   126	
   127	  useEffect(() => {
   128	    if (!dreamId) return;
   129	    let active = true;
   130	    fetchDreamById(dreamId)
   131	      .then((row) => {
   132	        if (!active || !row) return;
   133	        setDream({
   134	          dreamText: row.dream_text,
   135	          title: row.title,
   136	          mood: row.mood,
   137	          themes: row.themes,
   138	          summary: row.summary,
   139	        });
   140	      })
   141	      .catch((error) => console.warn('Could not load dream for the voice companion:', error))
   142	      // If it fails, the companion still works; it just starts without the dream.
   143	      .finally(() => {
   144	        if (active) setLoadingDream(false);
   145	      });
   146	    return () => {
   147	      active = false;
   148	    };
   149	  }, [dreamId]);
   150	
   151	  return { dream, loadingDream };
   152	}
   153	
   154	type ControlButtonProps = {
   155	  label: string;
   156	  onPress: () => void;
   157	  variant?: 'plain' | 'primary' | 'danger' | 'active';
   158	  disabled?: boolean;
   159	  wide?: boolean;
   160	};
   161	
   162	function ControlButton({ label, onPress, variant = 'plain', disabled = false, wide = false }: ControlButtonProps) {
   163	  return (
   164	    <Pressable
   165	      accessibilityRole="button"
   166	      onPress={onPress}
   167	      disabled={disabled}
   168	      style={({ pressed }) => [
   169	        styles.button,
   170	        wide && styles.buttonWide,
   171	        variant === 'primary' && styles.buttonPrimary,
   172	        variant === 'danger' && styles.buttonDanger,
   173	        variant === 'active' && styles.buttonActive,
   174	        pressed && styles.buttonPressed,
   175	        disabled && styles.buttonDisabled,
   176	      ]}>
   177	      <Text style={[styles.buttonText, variant === 'active' && styles.buttonTextActive]}>{label}</Text>
   178	    </Pressable>
   179	  );
   180	}
   181	
   182	const styles = StyleSheet.create({
   183	  screen: {
   184	    flex: 1,
   185	    backgroundColor: VoiceColors.background,
   186	    paddingHorizontal: Spacing.lg,
   187	  },
   188	  header: {
   189	    flexDirection: 'row',
   190	    alignItems: 'center',
   191	    paddingVertical: Spacing.sm,
   192	  },
   193	  close: {
   194	    fontSize: 20,
   195	    color: VoiceColors.textSecondary,
   196	    width: 32,
   197	  },
   198	  headerText: {
   199	    flex: 1,
   200	    alignItems: 'center',
   201	  },
   202	  headerSpacer: {
   203	    width: 32,
   204	  },
   205	  title: {
   206	    fontSize: 16,
   207	    fontWeight: '600',
   208	    color: VoiceColors.text,
   209	  },
   210	  subtitle: {
   211	    fontSize: 13,
   212	    color: VoiceColors.textSecondary,
   213	  },
   214	  orbArea: {
   215	    alignItems: 'center',
   216	    justifyContent: 'center',
   217	    paddingTop: Spacing.md,
   218	  },
   219	  statusRow: {
   220	    flexDirection: 'row',
   221	    alignItems: 'center',
   222	    gap: Spacing.sm,
   223	    marginTop: -Spacing.xl,
   224	    minHeight: 24,
   225	  },
   226	  status: {
   227	    fontSize: 17,
   228	    fontWeight: '600',
   229	    color: VoiceColors.text,
   230	    textAlign: 'center',
   231	  },
   232	  statusError: {
   233	    color: VoiceColors.error,
   234	    fontSize: 15,
   235	    fontWeight: '500',
   236	  },
   237	  hint: {
   238	    marginTop: Spacing.xs,
   239	    fontSize: 14,
   240	    color: VoiceColors.textSecondary,
   241	    textAlign: 'center',
   242	  },
   243	  transcript: {
   244	    flex: 1,
   245	    marginTop: Spacing.md,
   246	  },
   247	  controls: {
   248	    flexDirection: 'row',
   249	    gap: Spacing.sm,
   250	    paddingVertical: Spacing.md,
   251	  },
   252	  button: {
