########## services/dreams.ts ##########
     1	import { File } from 'expo-file-system';
     2	
     3	import { supabase } from '@/lib/supabase';
     4	import { toReadableError } from '@/services/function-errors';
     5	import type { Dream, DreamDetails } from '@/types/dream';
     6	import type { PatternReading } from '@/utils/patterns';
     7	import type { Ask, Fragment } from '@/utils/today';
     8	
     9	/**
    10	 * All database work for dreams lives here, so screens never talk to Supabase directly.
    11	 * Each function either returns data or throws an Error with a readable message.
    12	 */
    13	
    14	/** Saves a new dream and returns the saved row (including its new `id`). */
    15	export async function createDream(dreamText: string): Promise<Dream> {
    16	  const { data, error } = await supabase
    17	    .from('dreams')
    18	    .insert({ dream_text: dreamText.trim() })
    19	    .select()
    20	    .single();
    21	
    22	  if (error) throw new Error(error.message);
    23	  return data;
    24	}
    25	
    26	/** Returns every dream, newest first. */
    27	export async function fetchDreams(): Promise<Dream[]> {
    28	  const { data, error } = await supabase
    29	    .from('dreams')
    30	    .select('*')
    31	    .order('created_at', { ascending: false });
    32	
    33	  if (error) throw new Error(error.message);
    34	  return data;
    35	}
    36	
    37	/** Returns one dream, or `null` if no dream has that id. */
    38	export async function fetchDreamById(id: string): Promise<Dream | null> {
    39	  const { data, error } = await supabase.from('dreams').select('*').eq('id', id).maybeSingle();
    40	
    41	  if (error) throw new Error(error.message);
    42	  return data;
    43	}
    44	
    45	/** Saves the mood, people and places the dreamer added, and returns the updated dream. */
    46	export async function updateDreamDetails(dreamId: string, details: DreamDetails): Promise<Dream> {
    47	  const { data, error } = await supabase
    48	    .from('dreams')
    49	    .update(details)
    50	    .eq('id', dreamId)
    51	    .select()
    52	    .maybeSingle();
    53	
    54	  if (error) throw new Error(error.message);
    55	  // No row back means the database didn't allow the change (the details migration isn't applied).
    56	  if (!data) throw new Error('Your details couldn’t be saved yet. Please try again later.');
    57	  return data;
    58	}
    59	
    60	/** Saves the card colour picked on the Entries screen, and returns the updated dream. */
    61	export async function updateDreamColor(dreamId: string, color: string): Promise<Dream> {
    62	  const { data, error } = await supabase
    63	    .from('dreams')
    64	    .update({ color })
    65	    .eq('id', dreamId)
    66	    .select()
    67	    .maybeSingle();
    68	
    69	  if (error) throw new Error(error.message);
    70	  // No row back means the database didn't allow the change (the colour migration isn't applied).
    71	  if (!data) throw new Error('The colour couldn’t be saved yet. Please try again later.');
    72	  return data;
    73	}
    74	
    75	/** Deletes a dream for good. */
    76	export async function deleteDream(dreamId: string): Promise<void> {
    77	  const { data, error } = await supabase.from('dreams').delete().eq('id', dreamId).select('id');
    78	
    79	  if (error) throw new Error(error.message);
    80	  // Nothing deleted means the database didn't allow it (the delete migration isn't applied).
    81	  if (!data?.length) throw new Error('The dream couldn’t be deleted yet. Please try again later.');
    82	}
    83	
    84	/**
    85	 * Asks the `analyze-dream` Edge Function (server side) to create the AI reflection.
    86	 * The function calls Groq, saves the result on the dream, and returns the updated dream.
    87	 */
    88	export async function analyzeDream(dreamId: string): Promise<Dream> {
    89	  return invokeDreamFunction(
    90	    'analyze-dream',
    91	    dreamId,
    92	    'The AI reflection could not be created. Please try again.'
    93	  );
    94	}
    95	
    96	/**
    97	 * Asks the `generate-dream-image` Edge Function (server side) to paint the dream.
    98	 * The function calls Cloudflare Workers AI, stores the image in Supabase Storage,
    99	 * saves its link on the dream, and returns the updated dream.
   100	 */
   101	export async function generateDreamImage(dreamId: string): Promise<Dream> {
   102	  return invokeDreamFunction(
   103	    'generate-dream-image',
   104	    dreamId,
   105	    'The dream image could not be created. Please try again.'
   106	  );
   107	}
   108	
   109	/**
   110	 * Asks the `generate-dream-audio` Edge Function (server side) to read the reflection aloud.
   111	 * The function calls Groq Text-to-Speech, stores the WAV file in Supabase Storage,
   112	 * saves its link on the dream, and returns the updated dream.
   113	 */
   114	export async function generateDreamAudio(dreamId: string): Promise<Dream> {
   115	  return invokeDreamFunction(
   116	    'generate-dream-audio',
   117	    dreamId,
   118	    'The audio reflection could not be created. Please try again.'
   119	  );
   120	}
   121	
   122	/** Calls one of our Edge Functions with `{ dreamId }` and returns the updated dream it sends back. */
   123	async function invokeDreamFunction(
   124	  functionName: string,
   125	  dreamId: string,
   126	  fallbackMessage: string
   127	): Promise<Dream> {
   128	  const { data, error } = await supabase.functions.invoke<{ dream: Dream }>(functionName, {
   129	    body: { dreamId },
   130	  });
   131	
   132	  if (error) throw await toReadableError(error, fallbackMessage);
   133	  if (!data?.dream) {
   134	    throw new Error('The server sent an unexpected answer. Please try again.');
   135	  }
   136	  return data.dream;
   137	}
   138	
   139	/**
   140	 * Sends a voice recording to the `transcribe-dream` Edge Function (server side),
   141	 * which uses Groq Whisper, and returns the text. Returns '' if no words were heard.
   142	 * The recording itself is not stored anywhere.
   143	 */
   144	export async function transcribeDreamRecording(fileUri: string): Promise<string> {
   145	  const form = new FormData();
   146	  // Expo's `fetch` needs a real file object (with its bytes) for uploads, so we wrap the
   147	  // recording in expo-file-system's `File`. Its name keeps the extension (e.g. ".m4a").
   148	  form.append('audio', new File(fileUri));
   149	
   150	  const { data, error } = await supabase.functions.invoke<{ text: string }>('transcribe-dream', {
   151	    body: form,
   152	  });
   153	
   154	  if (error) {
   155	    throw await toReadableError(error, 'We couldn’t turn your recording into text. Please try again.');
   156	  }
   157	  if (typeof data?.text !== 'string') {
   158	    throw new Error('The server sent an unexpected answer. Please try again.');
   159	  }
   160	  return data.text;
   161	}
   162	
   163	/**
   164	 * Asks the `dream-fragments` Edge Function (Groq, server side) for the next question on the
   165	 * "talk it through" card, built on the answers so far. Nothing is saved.
   166	 */
   167	export async function askNextFragment(fragments: readonly Fragment[]): Promise<Ask> {
   168	  const { data, error } = await supabase.functions.invoke<Ask>('dream-fragments', {
   169	    body: { mode: 'ask', fragments },
   170	  });
   171	
   172	  if (error) throw await toReadableError(error, 'Afterdream lost its train of thought. Please try again.');
   173	  if (typeof data?.question !== 'string' || !Array.isArray(data.suggestions)) {
   174	    throw new Error('The server sent an unexpected answer. Please try again.');
   175	  }
   176	  return { question: data.question, suggestions: data.suggestions.filter((s) => typeof s === 'string') };
   177	}
   178	
   179	/** Has the `dream-fragments` Edge Function stitch the answers into one retelling of the dream. */
   180	export async function composeDreamFromFragments(fragments: readonly Fragment[]): Promise<string> {
   181	  const { data, error } = await supabase.functions.invoke<{ dream: string }>('dream-fragments', {
   182	    body: { mode: 'compose', fragments },
   183	  });
   184	
   185	  if (error) throw await toReadableError(error, 'The pieces couldn’t be put together right now. Please try again.');
   186	  if (typeof data?.dream !== 'string' || !data.dream.trim()) {
   187	    throw new Error('The server sent an unexpected answer. Please try again.');
   188	  }
   189	  return data.dream.trim();
   190	}
   191	
   192	/**
   193	 * Asks the `dream-patterns` Edge Function (Groq, server side) to read the newest dreams side
   194	 * by side: the thread through them, the dream cast, symbols and a question. Nothing is saved.
   195	 */
   196	export async function readDreamPatterns(): Promise<PatternReading> {
   197	  const { data, error } = await supabase.functions.invoke<{ reading: PatternReading }>('dream-patterns', {
   198	    body: { mode: 'read', timezoneOffset: new Date().getTimezoneOffset() },
   199	  });
   200	
   201	  if (error) throw await toReadableError(error, 'Your patterns couldn’t be read right now. Please try again.');
   202	  const reading = data?.reading;
   203	  if (
   204	    typeof reading?.thread?.title !== 'string' ||
   205	    typeof reading.question?.title !== 'string' ||
   206	    !Array.isArray(reading.cast) ||
   207	    !Array.isArray(reading.symbols)
   208	  ) {
   209	    throw new Error('The server sent an unexpected answer. Please try again.');
   210	  }
   211	  return reading;
   212	}

