     2	import { useState } from 'react';
     3	import { Alert, ScrollView, StyleSheet, Text, TextInput } from 'react-native';
     4	
     5	import { AppButton } from '@/components/app-button';
     6	import { Screen } from '@/components/screen';
     7	import { VoiceInput } from '@/components/voice-input';
     8	import { Colors, Radius, Spacing } from '@/constants/theme';
     9	import { useDreamRecorder } from '@/hooks/use-dream-recorder';
    10	import { analyzeDream, createDream } from '@/services/dreams';
    11	import type { Dream } from '@/types/dream';
    12	import { getErrorMessage } from '@/utils/errors';
    13	
    14	/** What the screen is doing: waiting for input, saving the dream, or waiting for the AI. */
    15	type Step = 'idle' | 'saving' | 'reflecting';
    16	
    17	const BUTTON_TITLES: Record<Step, string> = {
    18	  idle: 'Save Dream',
    19	  saving: 'Saving…',
    20	  reflecting: 'Reflecting on your dream…',
    21	};
    22	
    23	/** Record Dream screen ("/record"). */
    24	export default function RecordDreamScreen() {
    25	  const [text, setText] = useState('');
    26	  const [step, setStep] = useState<Step>('idle');
    27	
    28	  // Speaking is an alternative to typing: the words are added to the text box,
    29	  // where the user can still edit them before saving.
    30	  const voice = useDreamRecorder((spokenText) => {
    31	    setText((current) => (current.trim() ? `${current.trim()}\n\n${spokenText}` : spokenText));
    32	  });
    33	
    34	  const isBusy = step !== 'idle';
    35	  const isVoiceBusy = voice.phase !== 'idle';
    36	  const canSave = text.trim().length > 0 && !isVoiceBusy;
    37	
    38	  async function handleSave() {
    39	    // 1. Save the dream itself. If this fails, stay here and keep the text.
    40	    setStep('saving');
    41	    let dream: Dream;
    42	    try {
    43	      dream = await createDream(text);
    44	    } catch (error) {
    45	      Alert.alert('Could not save your dream', getErrorMessage(error));
    46	      setStep('idle');
    47	      return;
    48	    }
    49	
    50	    // 2. Ask for the AI reflection. If this fails the dream is still saved,
    51	    //    and the Dream Detail screen shows a "Try again" button.
    52	    setStep('reflecting');
    53	    try {
    54	      await analyzeDream(dream.id);
    55	    } catch (error) {
    56	      console.warn('AI reflection failed:', getErrorMessage(error));
    57	    }
    58	
    59	    // 3. Open the dream. `replace` so "back" returns to Home, not this form.
    60	    router.replace({ pathname: '/dream/[id]', params: { id: dream.id, tab: 'analysis' } });
    61	  }
    62	
    63	  return (
    64	    <Screen style={styles.screen}>
    65	      {/* Don't let the user leave halfway through saving. */}
    66	      <Stack.Screen options={{ headerBackVisible: !isBusy, gestureEnabled: !isBusy }} />
    67	      <ScrollView
    68	        contentContainerStyle={styles.content}
    69	        keyboardShouldPersistTaps="handled"
    70	        automaticallyAdjustKeyboardInsets>
    71	        <Text style={styles.title}>What did you dream?</Text>
    72	
    73	        <TextInput
    74	          style={styles.input}
    75	          value={text}
    76	          onChangeText={setText}
    77	          placeholder="I was flying over a city made of glass..."
    78	          placeholderTextColor={Colors.textSecondary}
    79	          multiline
    80	          autoFocus
    81	          editable={!isBusy && !isVoiceBusy}
    82	          textAlignVertical="top"
    83	        />
    84	
    85	        <VoiceInput
    86	          phase={voice.phase}
    87	          durationMillis={voice.durationMillis}
    88	          error={voice.error}
    89	          disabled={isBusy}
    90	          onStart={voice.start}

