     1	/**
     2	 * Types for the real-time voice companion (Deepgram Voice Agent API).
     3	 * Message shapes follow Deepgram's official Voice Agent v1 schema.
     4	 */
     5	
     6	// ---------------------------------------------------------------------------
     7	// Messages Deepgram sends to the app (JSON text frames). Audio arrives as binary frames.
     8	// ---------------------------------------------------------------------------
     9	
    10	export type ServerMessage =
    11	  | { type: 'Welcome'; request_id: string }
    12	  | { type: 'SettingsApplied' }
    13	  | { type: 'ConversationText'; role: 'user' | 'assistant'; content: string }
    14	  | { type: 'UserStartedSpeaking' }
    15	  | { type: 'AgentThinking'; content: string }
    16	  | { type: 'AgentStartedSpeaking' }
    17	  | { type: 'AgentAudioDone' }
    18	  | { type: 'Error'; description: string; code: string }
    19	  | { type: 'Warning'; description: string; code: string }
    20	  /** Anything we don't act on (e.g. LatencyReport, History) or couldn't read. */
    21	  | { type: 'Unknown'; originalType: string | null };
    22	
    23	// ---------------------------------------------------------------------------
    24	// The Settings message the app sends right after connecting.
    25	// ---------------------------------------------------------------------------
    26	
    27	export type HistoryMessage = { type: 'History'; role: 'user' | 'assistant'; content: string };
    28	
    29	export type AgentSettings = {
    30	  type: 'Settings';
    31	  audio: {
    32	    input: { encoding: 'linear16'; sample_rate: number };
    33	    output: { encoding: 'linear16'; sample_rate: number; container: 'none' };
    34	  };
    35	  agent: {
    36	    context?: { messages: HistoryMessage[] };
    37	    listen: { provider: { type: 'deepgram'; version: 'v2'; model: string } };
    38	    think: {
    39	      provider: { type: 'open_ai'; model: string; temperature?: number };
    40	      prompt: string;
    41	    };
    42	    speak: { provider: { type: 'deepgram'; model: string } };
    43	    greeting?: string;
    44	  };
    45	};
    46	
    47	// ---------------------------------------------------------------------------
    48	// App-side types.
    49	// ---------------------------------------------------------------------------
    50	
    51	/** The parts of a dream the companion may know about (nothing else is shared). */
    52	export type DreamContext = {
    53	  dreamText: string;
    54	  title?: string | null;
    55	  mood?: string | null;
    56	  themes?: string[] | null;
    57	  summary?: string | null;
    58	};
    59	
    60	export type TranscriptEntry = {
    61	  id: number;
    62	  role: 'user' | 'assistant';
    63	  text: string;
    64	};
    65	
    66	/** What the voice screen is doing. "Muted" is shown when `muted` is true while listening. */
    67	export type VoiceStatus =
    68	  | 'idle'
    69	  | 'connecting'
    70	  | 'listening'
    71	  | 'thinking'
    72	  | 'speaking'
    73	  | 'error'
    74	  | 'ended';
    75	
    76	/** Why a session failed, so the screen can offer the right button. */
    77	export type VoiceErrorKind = 'unsupported' | 'permission' | 'connection' | 'agent';

