########## voice-state.ts ##########
     1	/**
     2	 * The voice screen's state machine, as a React `useReducer` reducer.
     3	 * Plain TypeScript, so every transition can be unit tested.
     4	 */
     5	import type { TranscriptEntry, VoiceErrorKind, VoiceStatus } from './types';
     6	
     7	export type VoiceState = {
     8	  status: VoiceStatus;
     9	  muted: boolean;
    10	  transcript: TranscriptEntry[];
    11	  error: { kind: VoiceErrorKind; message: string } | null;
    12	  /** Deepgram has sent all audio for the current reply (it may still be playing). */
    13	  agentAudioDone: boolean;
    14	  nextTranscriptId: number;
    15	};
    16	
    17	export type VoiceAction =
    18	  | { type: 'connect' }
    19	  | { type: 'ready' }
    20	  | { type: 'userStartedSpeaking' }
    21	  | { type: 'agentThinking' }
    22	  | { type: 'agentStartedSpeaking' }
    23	  | { type: 'agentAudioDone' }
    24	  | { type: 'playbackDrained' }
    25	  | { type: 'transcript'; role: 'user' | 'assistant'; text: string }
    26	  | { type: 'toggleMute' }
    27	  | { type: 'error'; kind: VoiceErrorKind; message: string }
    28	  | { type: 'disconnected' }
    29	  | { type: 'ended' };
    30	
    31	export const initialVoiceState: VoiceState = {
    32	  status: 'idle',
    33	  muted: false,
    34	  transcript: [],
    35	  error: null,
    36	  agentAudioDone: false,
    37	  nextTranscriptId: 1,
    38	};
    39	
    40	export const CONNECTION_LOST_MESSAGE = 'The connection to your dream companion was lost.';
    41	
    42	/** Statuses in which a live conversation is running. */
    43	export function isLiveStatus(status: VoiceStatus) {
    44	  return status === 'listening' || status === 'thinking' || status === 'speaking';
    45	}
    46	
    47	export function voiceReducer(state: VoiceState, action: VoiceAction): VoiceState {
    48	  const live = isLiveStatus(state.status);
    49	
    50	  switch (action.type) {
    51	    case 'connect':
    52	      // Keep the transcript: a reconnect continues the same conversation.
    53	      return { ...state, status: 'connecting', error: null, agentAudioDone: false };
    54	
    55	    case 'ready':
    56	      return state.status === 'connecting' ? { ...state, status: 'listening' } : state;
    57	
    58	    case 'userStartedSpeaking':
    59	      // Barge-in: whatever the agent was doing, the user now has the floor.
    60	      return live ? { ...state, status: 'listening', agentAudioDone: false } : state;
    61	
    62	    case 'agentThinking':
    63	      return live ? { ...state, status: 'thinking' } : state;
    64	
    65	    case 'agentStartedSpeaking':
    66	      return live ? { ...state, status: 'speaking', agentAudioDone: false } : state;
    67	
    68	    case 'agentAudioDone':
    69	      return live ? { ...state, agentAudioDone: true } : state;
    70	
    71	    case 'playbackDrained':
    72	      // Only return to listening once Deepgram is done AND the last audio has played.
    73	      return state.status === 'speaking' && state.agentAudioDone
    74	        ? { ...state, status: 'listening', agentAudioDone: false }
    75	        : state;
    76	
    77	    case 'transcript': {
    78	      const text = action.text.trim();
    79	      if (!text) return state;
    80	      const last = state.transcript[state.transcript.length - 1];
    81	      // Several messages in a row from the same speaker read better as one bubble.
    82	      if (last && last.role === action.role) {
    83	        const merged = { ...last, text: `${last.text} ${text}` };
    84	        return { ...state, transcript: [...state.transcript.slice(0, -1), merged] };
    85	      }
    86	      return {
    87	        ...state,
    88	        transcript: [...state.transcript, { id: state.nextTranscriptId, role: action.role, text }],
    89	        nextTranscriptId: state.nextTranscriptId + 1,
    90	      };
    91	    }
    92	
    93	    case 'toggleMute':
    94	      return { ...state, muted: !state.muted };
    95	
    96	    case 'error':
    97	      return { ...state, status: 'error', error: { kind: action.kind, message: action.message } };
    98	
    99	    case 'disconnected':
   100	      // An unexpected close during a live or connecting session.
   101	      return live || state.status === 'connecting'
   102	        ? { ...state, status: 'error', error: { kind: 'connection', message: CONNECTION_LOST_MESSAGE } }
   103	        : state;
   104	
   105	    case 'ended':
   106	      return { ...state, status: 'ended', muted: false, agentAudioDone: false };
   107	  }
   108	}
   109	
   110	/** The label under the orb. */
   111	export function statusLabel(state: VoiceState) {
   112	  switch (state.status) {
   113	    case 'idle':
   114	      return 'Tap to start';
   115	    case 'connecting':
   116	      return 'Connecting…';
   117	    case 'listening':
   118	      return state.muted ? 'Muted' : 'Listening';
   119	    case 'thinking':
   120	      return 'Thinking…';
   121	    case 'speaking':
   122	      return 'Speaking';
   123	    case 'error':
   124	      return state.error?.message ?? 'Something went wrong.';
   125	    case 'ended':
   126	      return 'Conversation ended';
   127	  }
   128	}

