new = """/** What the screen is doing with the conversation once the talking has stopped. */
type SaveStep = 'none' | 'saving' | 'reflecting';

const SAVE_LABELS: Record<Exclude<SaveStep, 'none'>, string> = {
  saving: 'Saving your dream\\u2026',
  reflecting: 'Reading your dream\\u2026',
};

/**
 * Voice companion screen ("/voice", or "/voice?dreamId=<id>" to talk about a saved dream).
 * Real-time conversation with the Deepgram Voice Agent. Needs the native development build.
 *
 * Telling a new dream ("/voice"): when the conversation ends, what they said is saved as the
 * dream, sent to `analyze-dream` for the reading, and the Dream screen opens on its analysis.
 * Talking about a dream that is already saved ("/voice?dreamId=") never creates a second one.
 */
export default function VoiceScreen() {
  const { dreamId } = useLocalSearchParams<{ dreamId?: string }>();
  const { dream, loadingDream } = useDreamContext(dreamId);
  const { state, inputLevel, outputLevel, start, end, toggleMute } = useVoiceAgent(dream);
  const [saveStep, setSaveStep] = useState<SaveStep>('none');
  const [saveError, setSaveError] = useState<string | null>(null);

  const live = isLiveStatus(state.status);
  const busy = live || state.status === 'connecting';
  const saving = saveStep !== 'none';
  // Only a dream being told for the first time is worth saving, and only once they said enough.
  const canSave = !dreamId && canSaveTranscript(state.transcript);
  const canStart = !busy && !saving && !loadingDream && state.error?.kind !== 'unsupported';

  /** Saves what they told the companion, asks for the reading, then opens the dream. */
  async function saveConversation() {
    setSaveError(null);
    setSaveStep('saving');

    // 1. Save the dream in their own words. If this fails, the transcript stays on screen
    //    so nothing they said is lost and they can try again.
    let saved: Dream;
    try {
      saved = await createDream(dreamTextFromTranscript(state.transcript));
    } catch (error) {
      setSaveError(getErrorMessage(error));
      setSaveStep('none');
      return;
    }

    // 2. Ask for the reading. If this fails the dream is still saved, and the Dream
    //    screen shows its own "Try again".
    setSaveStep('reflecting');
    try {
      await analyzeDream(saved.id);
    } catch (error) {
      console.warn('AI reflection failed:', getErrorMessage(error));
    }

    // 3. Open it on the analysis tab. `replace` so "back" doesn't return to the call.
    router.replace({ pathname: '/dream/[id]', params: { id: saved.id, tab: 'analysis' } });
  }

  /** Ends the call, then turns it into a dream when there is one worth keeping. */
  function handleEnd() {
    end();
    if (canSave) void saveConversation();
  }

  function handleClose() {
    // Don't walk out halfway through saving; the dream would be left without its reading.
    if (saving) return;
    end();
    router.back();
  }
"""

