 1	/**
 2	 * Creates a short-lived Deepgram access token with Deepgram's token-based auth API
 3	 * (POST /v1/auth/grant). The permanent API key is only used here, on the server.
 4	 *
 5	 * No Supabase or Deno code here, so it can be unit tested with Node (see grant.test.ts).
 6	 */
 7	
 8	export const DEEPGRAM_GRANT_URL = 'https://api.deepgram.com/v1/auth/grant';
 9	
10	/**
11	 * How long the temporary token is valid. It only has to be valid while the phone opens the
12	 * WebSocket; an open Voice Agent connection keeps running after the token expires.
13	 */
14	export const TOKEN_TTL_SECONDS = 30;
15	const GRANT_TIMEOUT_MS = 10_000;
16	
17	export type TemporaryToken = {
18	  access_token: string;
19	  expires_in: number;
20	};
21	
